self.KB_CONTENT["card:752723"]={"id":"card:752723","ty":"card","sourceId":"752723","title":"『程式作業關聯建立作業』中的『關聯欄位起始碼 (MH011)』為何？","ver":"iGP","topic":"合併","keywords":["合併"],"y":"other","answer":"* 同資料長度(MH008)說明EX2，亦可參考主欄位合併(ML020)的說明(2. 合併不含分隔符號或3. 合併含分隔符號)。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
