self.KB_CONTENT["card:778147"]={"id":"card:778147","ty":"card","sourceId":"778147","title":"『歷史加工記錄表』中的『分類方式』為何？","ver":"GP4以上","topic":"分類","keywords":["分類","加工","商品","記錄"],"y":"other","answer":"* 共用參數設定作業中分類方式有『1』商品分類方式一、『2』商品分類方式二、『3』商品分類方式三及『4』商品分類方式四。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
