self.KB_CONTENT["card:757940"]={"id":"card:757940","ty":"card","sourceId":"757940","title":"『退貨單建立作業』中的『菸酒註記 (TI020)』為何？","ver":"iGP","topic":"貨單","keywords":["貨單","退貨","共用","註記"],"y":"other","answer":"* 不可空白。* 若共用參數設定之功能別設定為「台灣版」時，此欄位可輸入。* 若共用參數設定之功能別設定為「大陸版」時，此欄位不可輸入。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
